import type { ComponentPropsWithoutRef } from "react";
import { cn } from "../../lib/cn";
import "../../styles/table.css";

/** Wraps the table so wide content scrolls sideways on small screens instead of breaking the layout. */
export function Table({ className, ...props }: ComponentPropsWithoutRef<"table">) {
  return (
    <div className="eui-table-wrap">
      <table className={cn("eui-table", className)} {...props} />
    </div>
  );
}

export function TableHeader({ className, ...props }: ComponentPropsWithoutRef<"thead">) {
  return <thead className={cn("eui-table__head", className)} {...props} />;
}

export function TableBody({ className, ...props }: ComponentPropsWithoutRef<"tbody">) {
  return <tbody className={cn("eui-table__body", className)} {...props} />;
}

export function TableFooter({ className, ...props }: ComponentPropsWithoutRef<"tfoot">) {
  return <tfoot className={cn("eui-table__footer", className)} {...props} />;
}

export function TableRow({ className, ...props }: ComponentPropsWithoutRef<"tr">) {
  return <tr className={cn("eui-table__row", className)} {...props} />;
}

export function TableHead({ className, ...props }: ComponentPropsWithoutRef<"th">) {
  return <th scope="col" className={cn("eui-table__th", className)} {...props} />;
}

export function TableCell({ className, ...props }: ComponentPropsWithoutRef<"td">) {
  return <td className={cn("eui-table__td", className)} {...props} />;
}

export function TableCaption({ className, ...props }: ComponentPropsWithoutRef<"caption">) {
  return <caption className={cn("eui-table__caption", className)} {...props} />;
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Table. Hairline row dividers, muted headers, and horizontal scroll on the wrapper. */

.eui-table-wrap {
  position: relative;
  width: 100%;
  overflow-x: auto;
  border-radius: var(--eui-radius-base);
  box-shadow: inset 0 0 0 var(--eui-border-width) var(--eui-color-border);
}

.eui-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
  color: var(--eui-color-fg);
  font-variant-numeric: tabular-nums;
}

.eui-table__caption {
  padding: 12px 16px;
  text-align: left;
  font-size: 13px;
  color: var(--eui-color-fg-muted);
  caption-side: bottom;
}

.eui-table__th {
  height: 40px;
  padding: 0 16px;
  text-align: left;
  font-weight: 500;
  font-size: 13px;
  color: var(--eui-color-fg-muted);
  background-color: var(--eui-color-surface);
  border-bottom: var(--eui-border-width) solid var(--eui-color-border);
  white-space: nowrap;
}

.eui-table__td {
  height: 44px;
  padding: 0 16px;
  border-bottom: var(--eui-border-width) solid var(--eui-color-border);
  vertical-align: middle;
}

.eui-table__body .eui-table__row:last-child > .eui-table__td {
  border-bottom: 0;
}

.eui-table__body .eui-table__row {
  transition: background-color var(--eui-duration-fast) var(--eui-easing-out);
}

.eui-table__body .eui-table__row:hover {
  background-color: var(--eui-color-hover);
}

.eui-table__footer {
  background-color: var(--eui-color-surface);
  font-weight: 500;
}

.eui-table__footer .eui-table__td {
  border-bottom: 0;
  border-top: var(--eui-border-width) solid var(--eui-color-border);
}
